def transform(g):
    cells={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}
    candidates=[]
    if not cells: return [[0 for _ in row] for row in g]
    for r in range(len(g)-1):
      for c in range(len(g[0])-1):
        box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
        if box<=cells: candidates.append((box,1))
        for missing,col in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          s=box-{missing}
          if s<=cells: candidates.append((s,col))
    sols=[]
    def rec(rem, chosen):
      if not rem: sols.append(chosen); return
      x=min(rem)
      for sh,col in candidates:
        if x in sh and sh<=rem: rec(rem-sh, chosen+[(sh,col)])
    rec(cells,[])
    # choose first cover ordered by row-major anchor, then color
    out=[[0 for _ in row] for row in g]
    sol=sols[0]
    for sh,col in sol:
      for r,c in sh: out[r][c]=col
    return out, len(sols)
