source='''def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    candidates = []
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                candidates.append((box, 1))
            for missing, color in (((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = box - {missing}
                if shape <= cells:
                    candidates.append((shape, color))

    solutions = []
    def cover(remaining, chosen):
        if not remaining:
            solutions.append(chosen)
            return
        cell = min(remaining)
        for shape, color in candidates:
            if cell in shape and shape <= remaining:
                cover(remaining - shape, chosen + [(shape, color)])
    cover(cells, [])

    output = [[0 for _ in row] for row in grid]
    for shape, color in solutions[0]:
        for r, c in shape:
            output[r][c] = color
    return output
